use axum::Json;
use serde::Serialize;
use std::borrow::Cow;

#[derive(Debug, Serialize)]
pub enum SuccessResult {
    #[serde(rename = "success")]
    Success,
}

#[derive(Debug, Serialize)]
pub enum ErrorResult {
    #[serde(rename = "error")]
    Error,
}

#[derive(Debug, Serialize)]
pub enum EmptyMsg {
    #[serde(rename = "")]
    Empty,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum ErrorCode {
    BadRequest,
    BadEventQueueId,
}

#[derive(Debug, Serialize)]
pub struct JsonSuccess<T> {
    result: SuccessResult,
    msg: EmptyMsg,
    #[serde(flatten)]
    inner: T,
}

#[derive(Debug, Serialize)]
pub struct JsonError<'a> {
    result: ErrorResult,
    msg: Cow<'a, str>,
    code: ErrorCode,
}

pub fn json_success<T>(inner: T) -> Json<JsonSuccess<T>> {
    Json(JsonSuccess {
        result: SuccessResult::Success,
        msg: EmptyMsg::Empty,
        inner,
    })
}

pub fn json_error<'a>(message: impl Into<Cow<'a, str>>) -> Json<JsonError<'a>> {
    Json(JsonError {
        result: ErrorResult::Error,
        msg: message.into(),
        code: ErrorCode::BadRequest,
    })
}

pub fn json_error_code<'a>(
    message: impl Into<Cow<'a, str>>,
    code: ErrorCode,
) -> Json<JsonError<'a>> {
    Json(JsonError {
        result: ErrorResult::Error,
        msg: message.into(),
        code,
    })
}

use anyhow::Result;
use std::sync::Arc;
use tokio::signal::unix::{SignalKind, signal};
use tokio::sync::watch;

#[derive(Clone)]
pub struct Sender {
    tx: Arc<watch::Sender<bool>>,
}

#[derive(Clone)]
pub struct Receiver {
    rx: watch::Receiver<bool>,
}

pub fn channel() -> Result<(Sender, Receiver)> {
    let mut interrupt = signal(SignalKind::interrupt())?;
    let mut terminate = signal(SignalKind::terminate())?;
    let (tx, rx) = watch::channel(false);
    let sender = Sender { tx: Arc::new(tx) };
    tokio::spawn({
        let sender = sender.clone();
        async move {
            tokio::select! {
                _ = interrupt.recv() => (),
                _ = terminate.recv() => (),
            }
            sender.shutdown();
        }
    });
    Ok((sender, Receiver { rx }))
}

impl Sender {
    pub fn shutdown(&self) {
        _ = self.tx.send_if_modified(|sent| {
            !*sent && {
                tracing::info!("shutting down");
                *sent = true;
                true
            }
        });
    }

    pub fn on_error<T, E, U>(&self, fut: U) -> impl Future<Output = Result<T, E>> + use<T, E, U>
    where
        U: Future<Output = Result<T, E>>,
    {
        let sender = self.clone();
        async move {
            fut.await.inspect_err(|_error| {
                sender.shutdown();
            })
        }
    }
}

impl Receiver {
    pub async fn wait(&mut self) {
        if !*self.rx.borrow_and_update() {
            _ = self.rx.changed().await;
        }
    }
}

