use axum::body::{Body, Bytes};
use axum::http::{Request, StatusCode};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response, Result};
use http_body_util::BodyExt;
use std::sync::atomic::{AtomicU64, Ordering};

static REQUEST_NUMBER: AtomicU64 = AtomicU64::new(0);

// From axum/examples/print-request-response
pub async fn print_request_response(
    request: Request<Body>,
    next: Next,
) -> Result<impl IntoResponse> {
    let request_number = REQUEST_NUMBER.fetch_add(1, Ordering::SeqCst);

    tracing::debug!("<{request_number} {} {}", request.method(), request.uri());
    let (parts, body) = request.into_parts();
    let bytes = buffer_and_print("<", request_number, body).await?;
    let request = Request::from_parts(parts, Body::from(bytes));

    let response = next.run(request).await;

    tracing::debug!(">{request_number} {}", response.status());
    let (parts, body) = response.into_parts();
    let bytes = buffer_and_print(">", request_number, body).await?;
    let response = Response::from_parts(parts, Body::from(bytes));

    Ok(response)
}

async fn buffer_and_print<B>(direction: &str, request_number: u64, body: B) -> Result<Bytes>
where
    B: axum::body::HttpBody<Data = Bytes>,
    B::Error: std::fmt::Display,
{
    let bytes = body
        .collect()
        .await
        .map_err(|err| {
            (
                StatusCode::BAD_REQUEST,
                format!("failed to read {direction}{request_number} body: {err}"),
            )
        })?
        .to_bytes();

    if let Ok(body) = std::str::from_utf8(&bytes) {
        tracing::debug!("{direction}{request_number} body = {:?}", body);
    }

    Ok(bytes)
}

use sha2::{Digest, Sha256};

use crate::{
    avatar::AvatarSettings,
    types::{RealmId, UserId},
};

fn user_avatar_hash(uid: &str, avatar_version_str: &str, avatar_salt: &str) -> String {
    // WARNING: If this method is changed, you may need to do a migration
    // similar to zerver/migrations/0060_move_avatars_to_be_uid_based.py .
    //
    // The salt prevents unauthenticated clients from enumerating the
    // avatars of all users.

    let user_key = format!("{uid}:{avatar_version_str}:{avatar_salt}");

    let mut hasher = Sha256::new();
    hasher.update(user_key.as_bytes());

    hex::encode(hasher.finalize())[..40].to_string()
}

pub fn user_avatar_base_path_from_ids(
    user_profile_id: UserId,
    avatar_version: i32,
    realm_id: RealmId,
    settings: &AvatarSettings,
) -> String {
    let user_id_hash = user_avatar_hash(
        &user_profile_id.to_string(),
        &avatar_version.to_string(),
        &settings.avatar_salt,
    );
    format!("{realm_id}/{user_id_hash}")
}

use anyhow::Result;
use axum::Router;
use axum::middleware;
use axum::routing::{get, post};
use hyper_util::rt::TokioIo;
use std::net::SocketAddr;
use std::pin::pin;
use std::sync::Arc;
use tokio::net::TcpListener;
use tower_service::Service;

use crate::app_state::AppState;
use crate::auth::{api_auth, django_session_auth};
use crate::debug::print_request_response;
use crate::handlers;
use crate::shutdown;

pub struct AppServer {
    app: Router,
    listener: TcpListener,
    shutdown_rx: shutdown::Receiver,
}

impl AppServer {
    pub async fn new(address: &SocketAddr, state: Arc<AppState>) -> Result<AppServer> {
        let shutdown_rx = state.shutdown_rx.clone();

        let app = Router::new()
            .route("/", get(handlers::get_root))
            .route(
                "/api/internal/notify_tornado",
                post(handlers::post_notify_tornado),
            )
            .route(
                "/json/events",
                get(handlers::get_events)
                    .delete(handlers::delete_events)
                    .route_layer(middleware::map_request_with_state(
                        state.clone(),
                        django_session_auth,
                    )),
            )
            .route(
                "/api/v1/events",
                get(handlers::get_events)
                    .delete(handlers::delete_events)
                    .route_layer(middleware::map_request_with_state(state.clone(), api_auth)),
            )
            .route(
                "/api/v1/events/internal",
                post(handlers::post_events_internal),
            )
            .with_state(state)
            .layer(middleware::from_fn(print_request_response));

        let listener = TcpListener::bind(address).await?;
        tracing::info!("listening on {address}", address = listener.local_addr()?);
        Ok(AppServer {
            app,
            listener,
            shutdown_rx,
        })
    }

    pub async fn run(mut self) -> Result<()> {
        loop {
            let (socket, _remote_addr) = tokio::select! {
                 result = self.listener.accept() => result?,
                 () = self.shutdown_rx.wait() => return Ok(()),
            };
            let app = self.app.clone();
            let mut shutdown_rx = self.shutdown_rx.clone();
            tokio::spawn(async move {
                let socket = TokioIo::new(socket);
                let hyper_service =
                    hyper::service::service_fn(move |request| app.clone().call(request));
                let conn = hyper::server::conn::http1::Builder::new()
                    .serve_connection(socket, hyper_service)
                    .with_upgrades();
                let mut conn = pin!(conn);
                let result = tokio::select! {
                    result = conn.as_mut() => result,
                    () = shutdown_rx.wait() => {
                        conn.as_mut().graceful_shutdown();
                        conn.await
                    }
                };
                if let Err(err) = result {
                    tracing::debug!("failed to serve connection: {err:#}");
                }
            });
        }
    }
}

