#[derive(Parser)]
struct Cli {
    #[arg(long)]
    address: SocketAddr,
    #[arg(long)]
    secrets_file: String,
    #[arg(long)]
    rabbitmq_host: String,
    #[arg(long)]
    rabbitmq_user: String,
    #[arg(long)]
    rabbitmq_notify_queue: String,
    #[arg(long)]
    enable_gravatar: bool,
    #[arg(long)]
    default_avatar_uri: String,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Cli::parse();

    // TODO/boq: console_subscriber is only suitable in development, not production.
    console_subscriber::init();

    let (shutdown_tx, shutdown_rx) =
        shutdown::channel().with_context(|| "failed to initialize shutdown handler")?;

    let Secrets {
        local_database_password,
        rabbitmq_password,
        secret_key,
        shared_secret,
        avatar_salt,
    } = Secrets::load(&args.secrets_file).with_context(|| "failed to load secrets")?;

    // TODO/boq: support non-development database configuration
    let mut db_config = deadpool_postgres::Config::new();
    db_config.host = Some("localhost".to_string());
    db_config.user = Some("zulip".to_string());
    db_config.password = [REDACTED];
    db_config.dbname = Some("zulip".to_string());
    let db_pool = db_config.create_pool(
        Some(deadpool_postgres::Runtime::Tokio1),
        tokio_postgres::NoTls,
    )?;

    let rabbitmq = RabbitMQ::connect(
        args.rabbitmq_host,
        args.rabbitmq_user,
        rabbitmq_password,
        &args.rabbitmq_notify_queue,
    )
    .await
    .with_context(|| "failed to connect to RabbitMQ")?;

    let state = Arc::new(AppState {
        shared_secret,
        secret_key,
        avatar_settings: AvatarSettings {
            enable_gravatar: args.enable_gravatar,
            default_avatar_uri: args.default_avatar_uri,
            avatar_salt,
        },
        shutdown_rx,
        db_pool,
        queues: Mutex::new(Queues::new()),
        rabbitmq_channel: rabbitmq.channel.clone(),
    });

    let server = AppServer::new(&args.address, Arc::clone(&state))
        .await
        .with_context(|| "failed to start server")?;

    let (rabbitmq_result, server_result) = tokio::join!(
        tokio::spawn(shutdown_tx.on_error(rabbitmq.run(state))),
        tokio::spawn(shutdown_tx.on_error(server.run()))
    );
    rabbitmq_result
        .with_context(|| "RabbitMQ failed")?
        .with_context(|| "RabbitMQ failed")?;
    server_result
        .with_context(|| "server failed")?
        .with_context(|| "server failed")?;

    tracing::info!("exited");
    Ok(())
}

use anyhow::{Context, Error, Result};
use configparser::ini::{Ini, IniDefault};

pub struct Secrets {
    pub local_database_password: String,
    pub rabbitmq_password: String,
    pub secret_key: String,
    pub shared_secret: String,
    pub avatar_salt: String,
}

impl Secrets {
    pub fn load(secrets_file: &str) -> Result<Secrets> {
        let content = std::fs::read_to_string(secrets_file)
            .with_context(|| format!("failed to read {secrets_file}"))?;

        Self::parse(content)
    }

    fn parse(content: String) -> Result<Secrets> {
        let mut defaults = IniDefault::default();
        defaults.enable_inline_comments = false;
        let mut secrets_config = Ini::new_from_defaults(defaults);

        secrets_config.read(content).map_err(Error::msg)?;
        Ok(Secrets {
            local_database_password: [REDACTED]
                .get("secrets", "local_database_password")
                .with_context(|| "missing local_database_password")?,
            rabbitmq_password: [REDACTED]
                .get("secrets", "rabbitmq_password")
                .with_context(|| "missing rabbitmq_password")?,
            secret_key: secrets_config
                .get("secrets", "secret_key")
                .with_context(|| "missing secret_key")?,
            shared_secret: [REDACTED]
                .get("secrets", "shared_secret")
                .with_context(|| "missing shared_secret")?,
            avatar_salt: secrets_config
                .get("secrets", "avatar_salt")
                .with_context(|| "missing avatar_salt")?,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_secret_with_comment_characters() {
        // Zulip's secret_key is drawn from an alphabet that includes `#`.
        let content = String::from(
            "[secrets]\n\
             local_database_password = password\n\
             rabbitmq_password = password\n\
             secret_key = abc#def;ghi!@$%^&*(-_=+)\n\
             shared_secret = shared\n\
             avatar_salt = salt\n",
        );
        let secrets = Secrets::parse(content).unwrap();

        assert_eq!(secrets.secret_key, "abc#def;ghi!@$%^&*(-_=+)");
    }

    #[test]
    fn test_full_line_comments() {
        let content = String::from(
            "# A comment\n\
             ; Another comment\n\
             [secrets]\n\
             local_database_password = password\n\
             rabbitmq_password = password\n\
             # secret_key = commented out\n\
             secret_key = key\n\
             shared_secret = shared\n\
             avatar_salt = salt\n",
        );
        let secrets = Secrets::parse(content).unwrap();

        assert_eq!(secrets.secret_key, "key");
    }
}

use amq_protocol_types::{FieldTable, ShortString};
use amq_protocol_uri::{AMQPAuthority, AMQPQueryString, AMQPScheme, AMQPUri, AMQPUserInfo};
