// Keep these in sync with zerver/tornado/event_queue.py.
const DEFAULT_EVENT_QUEUE_TIMEOUT_SECS: u32 = 60 * 10;
const MOBILE_EVENT_QUEUE_TIMEOUT_SECS: u32 = 12 * 60 * 60;
const MAX_QUEUE_TIMEOUT_SECS: u32 = 7 * 24 * 60 * 60;

type EventId = i64;

